data.divi_custom_css:
.et_pb_section {
    padding: 0px 0;
}

.animated-blurb-img .et_pb_main_blurb_image  {
    -moz-transition: all 0.3s;
    -webkit-transition: all 0.3s;
    transition: all 0.3s;
}
 
.animated-blurb-img .et_pb_main_blurb_image:hover {
    -webkit-transform: scale(1.06);
    -moz-transform: scale(1.06);
    -o-transform: scale(1.06);
    -ms-transform: scale(1.06);
    transform: scale(1.06);
}

.et_pb_blurb_position_left .et_pb_blurb_container, 
.et_pb_blurb_position_right .et_pb_blurb_container {
     vertical-align: middle;
}

.et_pb_main_blurb_image {
    text-align: center;
    margin-bottom: 0px;
}

.et-cart-info {
    display: block;
    float: right !important;
}

.et-cart-info {
    visibility: visible !important;
}

#ie6 .et_pb_column, #ie7 .et_pb_column, #ie8 .et_pb_column { 
    margin-right: 30px; 
}

#ie7 #top-menu li {
    display: inline;
 }

#ie7 .bottom-nav li {
    display: inline-block;
    display: inline;
}

#ie7 #et-secondary-nav li {
    display: inline;
}

#ie7 .nav li ul {
    top: 50px;
}

#ie7 .et_pb_portfolio_grid .et_pb_portfolio_item,
#ie8 .et_pb_portfolio_grid .et_pb_portfolio_item {
    margin-right: 30px;
}

.project .entry-content {
    padding-top: 0px;
}

.et_pb_widget ul li a {
    text-transform: uppercase;
    display: block;
    margin-bottom: 0px;
    border-bottom: 1px solid #e2e2e2;
    padding: 3px 5px;
    position: relative;
}

.et_pb_widget ul li {
   margin-bottom: 0px;
   display: block;
}

.et_pb_widget a {
    text-transform: uppercase;
}

 .et_pb_widget_area .et_pb_widget.widget_nav_menu ul li.current-menu-item &gt; a {
    font-weight: bold;
    color: pink;
}

h4.widgettitle {
    font-size: 20px;
    text-align: center;
    text-transform: uppercase;
    font-weight: bold;
    color: white;
    background-color: gray;
    padding: 10px;
 }

@media only screen and ( min-width: 550px ) {
    .et_pb_blurb_content {
        max-width: 1200px;
    }
}

.et_pb_fullwidth_header_0.et_pb_fullwidth_header {
     padding: 7.7% 0;
    height: 0;

}

.et_pb_slider .et_pb_slide {
}

.et_pb_slide_description {
}

.et_pb_slide_content {
}

.et_pb_slide_content h1{
}

.et_pb_slide_content h2 {
}

.et_pb_slide_content h3 {
}

.inside-page .et_pb_specialty_column .et_pb_row_inner:nth-child(n+2) {
    padding-top: 0px !important;
} 

.et_pb_text p:last-of-type,
 .et_pb_blurb_content p:last-of-type {
    padding-bottom: 1em;
}
.et_pb_text p:last-child, 
 .et_pb_blurb_content p:last-child  {
    padding-bottom: 0em;
}

.et_pb_row, .container, .et_pb_slider .et_pb_container {
    width: 90%;
}
.et_pb_main_blurb_image {
    line-height: 0;
}
.et_pb_code_inner {
	line-height: 0px;
}
